-- =====================================================================
-- DỮ LIỆU MẪU CHO DATABASE: logistics_purchasing
-- Sinh tự động (Node.js, seeded random) để phục vụ demo/test báo cáo.
-- Giả định: các bảng đang RỖNG và cột IDENTITY bắt đầu từ 1, tăng dần 1
-- đơn vị mỗi dòng insert theo đúng thứ tự bên dưới (không insert cột
-- IDENTITY, để SQL Server tự sinh id).
-- product_id được sinh trùng dải 1..800 với product_id thực tế của
-- database multichannel_sales (theo đúng ghi chú trong file gốc: 2 DB
-- không có FK vật lý, toàn vẹn dữ liệu do tầng ứng dụng/ETL đảm bảo).
-- =====================================================================

